package ru.zhukhly.bank;
import android.app.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.Random;
final class DriftGame extends View {
 final Paint p=new Paint(3); final Random rng=new Random(); final String[] plates={"А111А 702","В777ОР 702","М123СК 702","В004КО 702","Х666АМ 702"}; final int[] colors={0xfff4f4fa,0xff8995a6,0xff252933,0xffcfa34b,0xffbd1739}; int plate=-1,color=-1,score,best; float angle; boolean held,running; long start,last; float elapsed; final android.content.SharedPreferences prefs;
 DriftGame(android.content.Context c){super(c);prefs=c.getSharedPreferences("drift",0);best=prefs.getInt("best",0);setLayerType(View.LAYER_TYPE_SOFTWARE,null);next();}
 static void open(Activity a){Dialog d=new Dialog(a,android.R.style.Theme_Material_NoActionBar);d.setContentView(new DriftGame(a));d.show();}
 void next(){plate=(plate+1+rng.nextInt(4))%5;color=(color+1+rng.nextInt(4))%5;score=0;angle=0;elapsed=0;running=false;held=false;invalidate();}
 void fill(int c){p.setShader(null);p.setColor(c);p.setStyle(Paint.Style.FILL);}
 void rect(Canvas c,float l,float t,float r,float b,float rad,int col){fill(col);c.drawRoundRect(l,t,r,b,rad,rad,p);}
 void text(Canvas c,String s,float x,float y,float size,int col){fill(col);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextAlign(Paint.Align.CENTER);c.drawText(s,x,y,p);}
 protected void onDraw(Canvas c){long now=SystemClock.uptimeMillis();if(running){float dt=Math.min(.05f,(now-last)/1000f);last=now;elapsed=(now-start)/1000f;angle+=( (held?36:0)-angle)*Math.min(1,dt*6);float target=18+16*(float)Math.sin(elapsed*1.7);if(Math.abs(angle-target)<12)score+=(int)(dt*1000);if(elapsed>=18){running=false;best=Math.max(best,score);prefs.edit().putInt("best",best).apply();}}
 c.save();c.scale(getWidth()/360f,getHeight()/700f);c.drawColor(0xff090e18);text(c,"ЖУХЛЫЙ ДРИФТЕР",180,42,22,0xffffd9df);text(c,"‹ Выход",43,72,13,0xffc9cbd5);text(c,"Рекорд "+best,280,72,13,0xffc9cbd5);
 rect(c,15,94,345,500,22,0xff19212d);c.save();c.clipRect(15,94,345,500);for(int i=-2;i<12;i++){float y=i*55+(elapsed*180)%55;rect(c,48,y,52,y+28,2,0xffff3157);rect(c,308,y,312,y+28,2,0xffff3157);rect(c,178,y,182,y+24,2,0xff66717d);}c.translate(180,310);c.rotate(-angle);for(int i=0;i<7;i++){fill((held?45:10)<<24|0xcccccc);c.drawCircle((i%2==0?-30:30)+(float)Math.sin(i+elapsed)*12,65+i*9,12+i*2,p);}rect(c,-39,-72,39,75,15,0xff080a0f);for(int i=0;i<4;i++){float x=i%2==0?-45:33,y=i<2?-49:40;rect(c,x,y,x+12,y+29,3,0xff08090b);}p.setShader(new LinearGradient(-40,-60,40,65,new int[]{colors[color],0xffe2e6ed,colors[color]},null,Shader.TileMode.CLAMP));c.drawRoundRect(-37,-70,37,72,12,12,p);rect(c,-27,-31,27,28,9,0xff121c2a);rect(c,-29,-45,29,-28,5,0xff35495b);rect(c,-28,30,28,45,5,0xff35495b);rect(c,-35,-65,-14,-58,3,0xffb8f4ff);rect(c,14,-65,35,-58,3,0xffb8f4ff);rect(c,-34,55,-15,62,3,0xffff244c);rect(c,15,55,34,62,3,0xffff244c);rect(c,-43,64,43,72,3,0xff151922);rect(c,-25,47,25,56,2,0xffeeeeee);text(c,plates[plate],0,54,6.5f,0xff111111);c.restore();text(c,plates[plate],180,115,14,0xffffffff);text(c,"Очки "+score,180,465,22,0xffffffff);float target=18+16*(float)Math.sin(elapsed*1.7);rect(c,30,515,330,530,7,0xff293647);rect(c,30+target/40*300-20,515,30+target/40*300+20,530,7,0xff39d5a0);rect(c,30+angle/40*300-3,510,30+angle/40*300+3,535,3,0xffffffff);text(c,running?"Осталось "+Math.max(0,18-(int)elapsed)+" сек.":elapsed>0?"Заезд завершён":"Попадай в зелёную зону",180,565,16,0xffe4e9f0);rect(c,24,585,336,650,20,0xffc51c48);text(c,running?"УДЕРЖИВАЙ ДЛЯ ДРИФТА":elapsed>0?"НОВЫЙ ЗАЕЗД":"СТАРТ",180,625,18,0xffffffff);text(c,"Бесплатная игра · очки за мастерство",180,680,12,0xffa5afbe);c.restore();if(running)postInvalidateOnAnimation();}
 public boolean onTouchEvent(android.view.MotionEvent e){float y=e.getY()*700/getHeight(),x=e.getX()*360/getWidth();if(e.getActionMasked()==0){if(y<90&&x<100){android.content.Context ctx=getContext();ViewParent par=getParent();android.view.KeyEvent k=new android.view.KeyEvent(0,4);getRootView().dispatchKeyEvent(k);getRootView().dispatchKeyEvent(new android.view.KeyEvent(1,4));return true;}if(y>575){if(!running){if(elapsed>0)next();running=true;start=last=SystemClock.uptimeMillis();}held=true;invalidate();}return true;}if(e.getActionMasked()==1||e.getActionMasked()==3){held=false;return true;}return true;}
}